INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e4678f69-6a8f-52b2-b1e5-4234c58ffabe', 'Turkey Turkish Commercial Law', 'Turkish Commercial Law', 'The corporate governance approach in this Law is based on four pillars: full transparency, fairness, accountability and responsibility. Full transparency and accountability is required in the company''s financial statements, boards of directors’ annual reports, independent audits, and transactional auditors. The board of directors of publicly held companies are now obliged to publish corporate governance reports which outline their policies and practices.', 'The corporate governance approach in this Law is based on four pillars: full transparency, fairness, accountability and responsibility. Full transparency and accountability is required in the company''s financial statements, boards of directors’ annual reports, independent audits, and transactional auditors. The board of directors of publicly held companies are now obliged to publish corporate governance reports which outline their policies and practices.', 'The corporate governance approach in this Law is based on four pillars: full transparency, fairness, accountability and responsibility. Full transparency and accountability is required in the company''s financial statements, boards of directors’ annual reports, independent audits, and transactional auditors. The board of directors of publicly held companies are now obliged to publish corporate governance reports which outline their policies and practices.', 'Turkey', 'climate', 'in_force', '2011-01-01'::date, 'Turkey', 'https://www.carrotsandsticks.org/policies/180_17', ARRAY['turkey', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7707a1dd-a02c-520f-a6b4-4ca8b39c780f', 'Turkey Energy Efficiency Law', 'Energy Efficiency Law', 'The purpose of this Law is to increase efficiency in using energy sources and energy in order to use energy effectively, avoid waste, ease the burden of energy costs on the economy and protect environment.', 'The purpose of this Law is to increase efficiency in using energy sources and energy in order to use energy effectively, avoid waste, ease the burden of energy costs on the economy and protect environment.', 'The purpose of this Law is to increase efficiency in using energy sources and energy in order to use energy effectively, avoid waste, ease the burden of energy costs on the economy and protect environment.', 'Turkey', 'climate', 'in_force', '2007-01-01'::date, 'Turkey', 'https://www.carrotsandsticks.org/policies/180_4', ARRAY['turkey', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('97acfac4-28c1-59fc-965b-6838385df7cc', 'Turkey Environment Law', 'Environment Law No. 2872 (1983)', 'The objective of this Law is to ensure the preservation of the environment, which is a common asset of all living beings, through sustainable environment and sustainable development principles.', 'The objective of this Law is to ensure the preservation of the environment, which is a common asset of all living beings, through sustainable environment and sustainable development principles.', 'The objective of this Law is to ensure the preservation of the environment, which is a common asset of all living beings, through sustainable environment and sustainable development principles.', 'Turkey', 'governance', 'in_force', '2006-01-01'::date, 'Turkey', 'https://www.carrotsandsticks.org/policies/180_12', ARRAY['turkey', 'other sustainability policy', 'regulations', 'sdg11', 'mandatory']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('27ee4255-a30f-5dc8-8f83-f877bd68180a', 'Turkey Corporate Governance Principles', 'Corporate Governance Principles, 2003', 'The Principles mainly address publicly held joint stock companies. However, it is considered that other joint stock companies and institutions, active in private and public sector, may also implement these Principles.', 'The Principles mainly address publicly held joint stock companies. However, it is considered that other joint stock companies and institutions, active in private and public sector, may also implement these Principles.', 'The Principles mainly address publicly held joint stock companies. However, it is considered that other joint stock companies and institutions, active in private and public sector, may also implement these Principles.', 'Turkey', 'governance', 'in_force', '2003-01-01'::date, 'Turkey', 'https://www.carrotsandsticks.org/policies/180_15', ARRAY['turkey', 'guidance_frameworks', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9fdcd75b-77e3-5782-931f-f4ba51b8f99a', 'Turkey Consumer Protection as Amended by Act', 'Act No. 4077 on Consumer Protection as Amended by Act No. 4822', 'The purpose of this act is to take measures aimed at protecting the health, safety and economic interests of consumers in line with the public good, building consumer awareness, indemnifying losses incurred by consumers and protecting them against environmental hazards; to promote consumer initiatives aimed at protecting consumer interests and to encourage volunteer organizations aimed at devising consumer-related policies.', 'The purpose of this act is to take measures aimed at protecting the health, safety and economic interests of consumers in line with the public good, building consumer awareness, indemnifying losses incurred by consumers and protecting them against environmental hazards; to promote consumer initiatives aimed at protecting consumer interests and to encourage volunteer organizations aimed at devising consumer-related policies.', 'The purpose of this act is to take measures aimed at protecting the health, safety and economic interests of consumers in line with the public good, building consumer awareness, indemnifying losses incurred by consumers and protecting them against environmental hazards; to promote consumer initiatives aimed at protecting consumer interests and to encourage volunteer organizations aimed at devising consumer-related policies.', 'Turkey', 'governance', 'in_force', '2003-01-01'::date, 'Turkey', 'https://www.carrotsandsticks.org/policies/180_8', ARRAY['turkey', 'other sustainability policy', 'regulations', 'mandatory', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7e4e4f5d-6e80-5a96-961e-282879984507', 'Turkey Labour Law', 'Labour Law No. 4857', 'The objective of this Law is to regulate the rights and obligations regarding working conditions and work environment of employers and workers employed based on a labour contract.', 'The objective of this Law is to regulate the rights and obligations regarding working conditions and work environment of employers and workers employed based on a labour contract.', 'The objective of this Law is to regulate the rights and obligations regarding working conditions and work environment of employers and workers employed based on a labour contract.', 'Turkey', 'social', 'in_force', '2003-01-01'::date, 'Turkey', 'https://www.carrotsandsticks.org/policies/180_9', ARRAY['turkey', 'sdg8', 'other sustainability policy', 'regulations', 'mandatory']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('818020d0-000a-5e08-bbf2-cf2711d51136', 'Uganda National Action Plan on Business and Human Rights', 'National Action Plan on Business and Human Rights', 'The Uganda National Action Plan on Business and Human Rights (NAP) is a government initiative that seeks to ensure respect for human rights by businesses operating in Uganda. The NAP recognizes that businesses have a responsibility to respect human rights and seeks to ensure that businesses in Uganda are held accountable for any human rights violations they may commit. The NAP outlines several key principles for businesses to follow, including the need to conduct human rights due diligence, to engage with stakeholders and affected communities, and to have effective grievance mechanisms in place. It also sets out a framework for monitoring and reporting on business and human rights, with a focus on transparency, accountability, and participation. The NAP represents an important step forward in promoting responsible business conduct and protecting human rights in Uganda. While the plan is not mandatory for companies, it provides a framework for businesses to align their operations with international human rights standards and to contribute to sustainable development in Uganda. However, companies operating in Uganda are expected to comply with the country''s legal and regulatory framework, which includes laws and regulations related to human rights, labor standards, environmental protection, and other areas of social responsibility.', 'The Uganda National Action Plan on Business and Human Rights (NAP) is a government initiative that seeks to ensure respect for human rights by businesses operating in Uganda. The NAP recognizes that businesses have a responsibility to respect human rights and seeks to ensure that businesses in Uganda are held accountable for any human rights violations they may commit. The NAP outlines several key principles for businesses to follow, including the need to conduct human rights due diligence, to engage with stakeholders and affected communities, and to have effective grievance mechanisms in place. It also sets out a framework for monitoring and reporting on business and human rights, with a focus on transparency, accountability, and participation. The NAP represents an important step forward in promoting responsible business conduct and protecting human rights in Uganda. While the plan is not mandatory for companies, it provides a framework for businesses to align their operations with international human rights standards and to contribute to sustainable development in Uganda. However, companies operating in Uganda are expected to comply with the country''s legal and regulatory framework, which includes laws and regulations related to human rights, labor standards, environmental protection, and other areas of social responsibility.', 'The Uganda National Action Plan on Business and Human Rights (NAP) is a government initiative that seeks to ensure respect for human rights by businesses operating in Uganda. The NAP recognizes that businesses have a responsibility to respect human rights and seeks to ensure that businesses in Uganda are held accountable for any human rights violations they may commit. The NAP outlines several key principles for businesses to follow, including the need to conduct human rights due diligence, to engage with stakeholders and affected communities, and to have effective grievance mechanisms in place. It also sets out a framework for monitoring and reporting on business and human rights, with a focus on transparency, accountability, and participation. The NAP represents an important step forward in promoting responsible business conduct and protecting human rights in Uganda. While the plan is not mandatory for companies, it provides a framework for businesses to align their operations with international human rights standards and to contribute to sustainable development in Uganda. However, companies operating in Uganda are expected to comply with the country''s legal and regulatory framework, which includes laws and regulations related to human rights, labor standards, environmental protection, and other areas of social responsibility.', 'Uganda', 'climate', 'in_force', '2021-01-01'::date, 'Uganda', 'https://www.carrotsandsticks.org/policies/181_2', ARRAY['sdg8', 'regulations', 'mandatory', 'sdg5', 'uganda', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6498e18f-4abe-5193-8212-8911fb29c4ac', 'Uganda Capital Markets Corporate Governance Guidelines', 'The Capital Markets Corporate Governance Guidelines, 2003', 'The objective of these Guidelines is to strengthen corporate governance practices by listed companies in Uganda and promote the standards of self-regulation so as to bring the level of governance in line with international trends.', 'The objective of these Guidelines is to strengthen corporate governance practices by listed companies in Uganda and promote the standards of self-regulation so as to bring the level of governance in line with international trends.', 'The objective of these Guidelines is to strengthen corporate governance practices by listed companies in Uganda and promote the standards of self-regulation so as to bring the level of governance in line with international trends.', 'Uganda', 'governance', 'in_force', '2003-01-01'::date, 'Uganda', 'https://www.carrotsandsticks.org/policies/181_1', ARRAY['guidance_frameworks', 'other sustainability policy', 'uganda', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('90de0949-da8f-56b3-8c16-3602b435cd30', 'Ukraine NBU Sustainable Finance Development Policy', 'NBU Sustainable Finance Development Policy', 'Policy mission is to form a holistic vision of the key principles of sustainable finance development in Ukraine and the actions of the NBU necessary to implement these principles and to ensure that both banks and nonbank financial institutions consistently adapt to changes that will promote financial stability. Policy goals include: 1) to facilitate sustainable economic development of Ukraine 2) to promote environmental consciousness and social responsibility in Ukraine’s financial sector 3) to ensure that financial institutions regulated by the NBU comply with environmental objectives, the principles of sustainable economic activity, and the principle of prioritizing energy efficiency, which are identified by the European Green Pact 4) to help the development of a closed-loop economy in Ukraine as a decisive factor in achieving a climate-neutral, resource-efficient, and competitive economy.', 'Policy mission is to form a holistic vision of the key principles of sustainable finance development in Ukraine and the actions of the NBU necessary to implement these principles and to ensure that both banks and nonbank financial institutions consistently adapt to changes that will promote financial stability. Policy goals include: 1) to facilitate sustainable economic development of Ukraine 2) to promote environmental consciousness and social responsibility in Ukraine’s financial sector 3) to ensure that financial institutions regulated by the NBU comply with environmental objectives, the principles of sustainable economic activity, and the principle of prioritizing energy efficiency, which are identified by the European Green Pact 4) to help the development of a closed-loop economy in Ukraine as a decisive factor in achieving a climate-neutral, resource-efficient, and competitive economy.', 'Policy mission is to form a holistic vision of the key principles of sustainable finance development in Ukraine and the actions of the NBU necessary to implement these principles and to ensure that both banks and nonbank financial institutions consistently adapt to changes that will promote financial stability. Policy goals include: 1) to facilitate sustainable economic development of Ukraine 2) to promote environmental consciousness and social responsibility in Ukraine’s financial sector 3) to ensure that financial institutions regulated by the NBU comply with environmental objectives, the principles of sustainable economic activity, and the principle of prioritizing energy efficiency, which are identified by the European Green Pact 4) to help the development of a closed-loop economy in Ukraine as a decisive factor in achieving a climate-neutral, resource-efficient, and competitive economy.', 'Ukraine', 'climate', 'in_force', '2021-01-01'::date, 'Ukraine', 'https://www.carrotsandsticks.org/policies/182_8', ARRAY['sdg13', 'sdg7', 'mandatory', 'ukraine', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('df45802d-c9cf-5cfd-8a22-65f9316985ef', 'Ukraine Core Code of Corporate Governance: Requirements and Recommendations', 'The Core Code of Corporate Governance: Requirements and Recommendations, 2020', 'This Code is intended to strengthen the confidence of investors in Ukraine’s listed companies and strengthen confidence in Ukraine’s capital market. It spells out the basic requirements set down under law and regulation, and adds best practice recommendations that are designed to meet the expectations of investors. It also defines the distinct roles of shareholders, boards and management in the governance and operations of the Company.', 'This Code is intended to strengthen the confidence of investors in Ukraine’s listed companies and strengthen confidence in Ukraine’s capital market. It spells out the basic requirements set down under law and regulation, and adds best practice recommendations that are designed to meet the expectations of investors. It also defines the distinct roles of shareholders, boards and management in the governance and operations of the Company.', 'This Code is intended to strengthen the confidence of investors in Ukraine’s listed companies and strengthen confidence in Ukraine’s capital market. It spells out the basic requirements set down under law and regulation, and adds best practice recommendations that are designed to meet the expectations of investors. It also defines the distinct roles of shareholders, boards and management in the governance and operations of the Company.', 'Ukraine', 'governance', 'in_force', '2020-01-01'::date, 'Ukraine', 'https://www.carrotsandsticks.org/policies/182_5', ARRAY['guidance_frameworks', 'ukraine', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5ec9ffdf-177b-5821-9ef1-66aebfa80a91', 'Ukraine Handbook on Sustainable Public Procurement', 'Handbook on Sustainable Public Procurement', 'This handbook contains a basic information about benefits and advantages of the sustainable public procurement for government and public authorities; a step–by–step explanations how to transform a procurement process into sustainable one and to use it in practice. Moreover, it provides detailed information about integration of sustainability criteria into procurement process including supplier qualification, technical specifications, award criteria and contract conditions with examples for the three priority product groups.', 'This handbook contains a basic information about benefits and advantages of the sustainable public procurement for government and public authorities; a step–by–step explanations how to transform a procurement process into sustainable one and to use it in practice. Moreover, it provides detailed information about integration of sustainability criteria into procurement process including supplier qualification, technical specifications, award criteria and contract conditions with examples for the three priority product groups.', 'This handbook contains a basic information about benefits and advantages of the sustainable public procurement for government and public authorities; a step–by–step explanations how to transform a procurement process into sustainable one and to use it in practice. Moreover, it provides detailed information about integration of sustainability criteria into procurement process including supplier qualification, technical specifications, award criteria and contract conditions with examples for the three priority product groups.', 'Ukraine', 'circularity', 'in_force', '2016-01-01'::date, 'Ukraine', 'https://www.carrotsandsticks.org/policies/182_13', ARRAY['regulations', 'mandatory', 'ukraine', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a1e01a86-e71d-552b-b430-f364cfcd54f5', 'Ukraine Amendments to the Law on Banks and Banking', 'Law No. 1587 on Amendments to the Law on Banks and Banking Activities to Determine the Features of Corporate Governance in Banks', 'This law provides amendments to the Law on Banks and Banking Activity, by outlining the corporate governance structure and management of banks. This includes the mandatory responsibilities of the highest governing body, including internal control, general meetings, the role of the Board of Directors, and risk management and internal audit processes. This law also outlines the approval of annual financial results of the bank and the role of the Audit Committee.', 'This law provides amendments to the Law on Banks and Banking Activity, by outlining the corporate governance structure and management of banks. This includes the mandatory responsibilities of the highest governing body, including internal control, general meetings, the role of the Board of Directors, and risk management and internal audit processes. This law also outlines the approval of annual financial results of the bank and the role of the Audit Committee.', 'This law provides amendments to the Law on Banks and Banking Activity, by outlining the corporate governance structure and management of banks. This includes the mandatory responsibilities of the highest governing body, including internal control, general meetings, the role of the Board of Directors, and risk management and internal audit processes. This law also outlines the approval of annual financial results of the bank and the role of the Audit Committee.', 'Ukraine', 'governance', 'in_force', '2014-01-01'::date, 'Ukraine', 'https://www.carrotsandsticks.org/policies/182_11', ARRAY['regulations', 'mandatory', 'ukraine', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('95b2e9b9-915d-5291-8ca8-5e919775d98f', 'Recommendations on the governance of state-owned enterprises of Ukraine', 'Recommendations on the governance of state-owned enterprises of Ukraine, 2014', 'The UCGA Recommendations have the overall goal of improving the exercise of state ownership and SOE management.', 'The UCGA Recommendations have the overall goal of improving the exercise of state ownership and SOE management.', 'The UCGA Recommendations have the overall goal of improving the exercise of state ownership and SOE management.', 'Ukraine', 'governance', 'in_force', '2014-01-01'::date, 'Ukraine', 'https://www.carrotsandsticks.org/policies/182_6', ARRAY['guidance_frameworks', 'other sustainability policy', 'ukraine', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('36d08e33-e153-51c7-a323-ee0d3d307ede', 'Ukraine Law VI on Employment', 'Law No. 5067-VI on Employment', 'Enterprises, institutions and organizations with more than 20 full time employees within a calendar year are required to employ a set quota of 5% employees who are categorized as citizens with additional safeguards (Article 14). Mandatory employers who are subject to this quota must annually inform the central executive body of their compliance to this requirement.', 'Enterprises, institutions and organizations with more than 20 full time employees within a calendar year are required to employ a set quota of 5% employees who are categorized as citizens with additional safeguards (Article 14). Mandatory employers who are subject to this quota must annually inform the central executive body of their compliance to this requirement.', 'Enterprises, institutions and organizations with more than 20 full time employees within a calendar year are required to employ a set quota of 5% employees who are categorized as citizens with additional safeguards (Article 14). Mandatory employers who are subject to this quota must annually inform the central executive body of their compliance to this requirement.', 'Ukraine', 'social', 'in_force', '2013-01-01'::date, 'Ukraine', 'https://www.carrotsandsticks.org/policies/182_12', ARRAY['sdg8', 'regulations', 'mandatory', 'ukraine', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4890c0a9-0056-5565-a93d-6cb8aca18c67', 'Ukraine Ukrainian Corporate Governance Principles', 'Ukrainian Corporate Governance Principles, 2003', 'The purpose of the Principles of Corporate Governance of Ukraine is to lay down the principles and recommendations, based on international best practices of corporate governance and tailored to Ukraine’s needs and experience, that are necessary for the development of good corporate governance in Ukraine.', 'The purpose of the Principles of Corporate Governance of Ukraine is to lay down the principles and recommendations, based on international best practices of corporate governance and tailored to Ukraine’s needs and experience, that are necessary for the development of good corporate governance in Ukraine.', 'The purpose of the Principles of Corporate Governance of Ukraine is to lay down the principles and recommendations, based on international best practices of corporate governance and tailored to Ukraine’s needs and experience, that are necessary for the development of good corporate governance in Ukraine.', 'Ukraine', 'governance', 'in_force', '2003-01-01'::date, 'Ukraine', 'https://www.carrotsandsticks.org/policies/182_1', ARRAY['guidance_frameworks', 'other sustainability policy', 'ukraine', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b0879653-bfaf-5b36-ae60-7e0db5231b30', 'Law XIV on Accounting and Financial Reporting in Ukraine', 'Law No. 996-XIV on Accounting and Financial Reporting in Ukraine', 'Businesses are required to prepare financial statements signed by the director and accountant of the company. These statements must include the balance sheet, financial results, cash flow statements, and statement of changes in equity. The financial statements should be prepared in accordance with international accounting standards.', 'Businesses are required to prepare financial statements signed by the director and accountant of the company. These statements must include the balance sheet, financial results, cash flow statements, and statement of changes in equity. The financial statements should be prepared in accordance with international accounting standards.', 'Businesses are required to prepare financial statements signed by the director and accountant of the company. These statements must include the balance sheet, financial results, cash flow statements, and statement of changes in equity. The financial statements should be prepared in accordance with international accounting standards.', 'Ukraine', 'climate', 'in_force', '1999-01-01'::date, 'Ukraine', 'https://www.carrotsandsticks.org/policies/182_9', ARRAY['disclosure', 'ukraine', 'mandatory', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a769a1ec-e843-5e2c-bdcd-4cfc36721c87', 'Ukraine Law XII on the Protection of the Natural', 'Law No. 1264-XII on the Protection of the Natural Environment', 'In the case of an accident that causes pollution of the environment, the officials or owners of the enterprise must inform the local authorities and local population about the accident and the measures taken to mitigate the consequences of the accident.', 'In the case of an accident that causes pollution of the environment, the officials or owners of the enterprise must inform the local authorities and local population about the accident and the measures taken to mitigate the consequences of the accident.', 'In the case of an accident that causes pollution of the environment, the officials or owners of the enterprise must inform the local authorities and local population about the accident and the measures taken to mitigate the consequences of the accident.', 'Ukraine', 'governance', 'in_force', '1995-01-01'::date, 'Ukraine', 'https://www.carrotsandsticks.org/policies/182_7', ARRAY['ukraine', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('761744d7-c52d-5080-90c4-24b9f651a2de', 'UAE Sustainable Finance Framework 2021', 'UAE Sustainable Finance Framework 2021 - 2023', 'The UAE Sustainable Finance Framework (2021-2031) sets a comprehensive strategy to integrate sustainability into the UAE’s financial sector, supporting its transition to a net-zero and sustainable economy. The framework outlines key objectives to mobilize capital for green and sustainable projects, align financial practices with global standards, and foster transparency and accountability in ESG disclosures.

Key pillars include:

Regulatory Framework Development:

Establishing guidelines and taxonomies to define sustainable and transition activities.

Harmonizing domestic regulations with international standards, such as the EU Green Taxonomy and TCFD.

Capacity Building and Innovation:

Promoting education and awareness in sustainable finance.

Supporting green fintech and innovative financial products.

Disclosure and Transparency:

Recommending mandatory ESG disclosures aligned with globally recognized frameworks.

Emphasizing climate-related financial risk reporting.

Collaboration and Engagement:

Engaging stakeholders to foster partnerships and public-private collaboration for sustainability.

The framework positions the UAE as a regional leader in sustainable finance, contributing to global efforts in achieving the United Nations Sustainable Development Goals (SDGs).', 'The UAE Sustainable Finance Framework (2021-2031) sets a comprehensive strategy to integrate sustainability into the UAE’s financial sector, supporting its transition to a net-zero and sustainable economy. The framework outlines key objectives to mobilize capital for green and sustainable projects, align financial practices with global standards, and foster transparency and accountability in ESG disclosures.

Key pillars include:

Regulatory Framework Development:

Establishing guidelines and taxonomies to define sustainable and transition activities.

Harmonizing domestic regulations with international standards, such as the EU Green Taxonomy and TCFD.

Capacity Building and Innovation:

Promoting education and awareness in sustainable finance.

Supporting green fintech and innovative financial products.

Disclosure and Transparency:

Recommending mandatory ESG disclosures aligned with globally recognized frameworks.

Emphasizing climate-related financial risk reporting.

Collaboration and Engagement:

Engaging stakeholders to foster partnerships and public-private collaboration for sustainability.

The framework positions the UAE as a regional leader in sustainable finance, contributing to global efforts in achieving the United Nations Sustainable Development Goals (SDGs).', 'The UAE Sustainable Finance Framework (2021-2031) sets a comprehensive strategy to integrate sustainability into the UAE’s financial sector, supporting its transition to a net-zero and sustainable economy. The framework outlines key objectives to mobilize capital for green and sustainable projects, align financial practices with global standards, and foster transparency and accountability in ESG disclosures.

Key pillars include:

