INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c3275d5f-e2ac-5cec-95da-f241ab5b0877', 'UAE Guiding Principles on Sustainable Finance', 'Guiding Principles on Sustainable Finance, 2021', 'The principles aim to facilitate the UAE’s transition to a more sustainable and diversified economy, in part through mitigating the risks of reduced global demand for oil, as well as addressing the physical and financial risks of climate change. It covers the integration of ESG factors into governance, strategy, and risk management, the adoption of a minimum eligibility requirement to help identify sustainable financial products; and the promotion of appropriate ESG-related reporting and disclosures.', 'The principles aim to facilitate the UAE’s transition to a more sustainable and diversified economy, in part through mitigating the risks of reduced global demand for oil, as well as addressing the physical and financial risks of climate change. It covers the integration of ESG factors into governance, strategy, and risk management, the adoption of a minimum eligibility requirement to help identify sustainable financial products; and the promotion of appropriate ESG-related reporting and disclosures.', 'The principles aim to facilitate the UAE’s transition to a more sustainable and diversified economy, in part through mitigating the risks of reduced global demand for oil, as well as addressing the physical and financial risks of climate change. It covers the integration of ESG factors into governance, strategy, and risk management, the adoption of a minimum eligibility requirement to help identify sustainable financial products; and the promotion of appropriate ESG-related reporting and disclosures.', 'UAE', 'climate', 'in_force', '2021-01-01'::date, 'United Arab Emirates', 'https://www.carrotsandsticks.org/policies/183_15', ARRAY['guidance_frameworks', 'sdg13', 'uae', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4293abab-023e-56da-8994-17f5e3117458', 'UAE Due Diligence Regulations for Responsible Sourcing of Gold', 'Due Diligence Regulations for Responsible Sourcing of Gold', 'The regulations require all gold and precious metals refineries in the UAE to undergo a due diligence process to ensure that they only source gold from responsible and sustainable sources. Refineries must also obtain a responsible supply chain certification from a recognized international organization. In addition, the regulations require all gold and precious metals traders to implement a responsible sourcing policy and conduct due diligence on their suppliers to ensure that they also adhere to responsible and sustainable sourcing practices. The UAE government has also established a national committee to oversee the implementation of these regulations and ensure compliance across the gold industry. Failure to comply with the regulations can result in penalties and revocation of licenses.', 'The regulations require all gold and precious metals refineries in the UAE to undergo a due diligence process to ensure that they only source gold from responsible and sustainable sources. Refineries must also obtain a responsible supply chain certification from a recognized international organization. In addition, the regulations require all gold and precious metals traders to implement a responsible sourcing policy and conduct due diligence on their suppliers to ensure that they also adhere to responsible and sustainable sourcing practices. The UAE government has also established a national committee to oversee the implementation of these regulations and ensure compliance across the gold industry. Failure to comply with the regulations can result in penalties and revocation of licenses.', 'The regulations require all gold and precious metals refineries in the UAE to undergo a due diligence process to ensure that they only source gold from responsible and sustainable sources. Refineries must also obtain a responsible supply chain certification from a recognized international organization. In addition, the regulations require all gold and precious metals traders to implement a responsible sourcing policy and conduct due diligence on their suppliers to ensure that they also adhere to responsible and sustainable sourcing practices. The UAE government has also established a national committee to oversee the implementation of these regulations and ensure compliance across the gold industry. Failure to comply with the regulations can result in penalties and revocation of licenses.', 'UAE', 'climate', 'in_force', '2021-01-01'::date, 'United Arab Emirates', 'https://www.carrotsandsticks.org/policies/183_16', ARRAY['regulations', 'mandatory', 'uae', 'sdg12', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8a24b921-36be-5bd3-8c0a-0bf5cca52cef', 'UAE Chairman of Authority’s Board of Directors’ Decision no', 'Chairman of Authority’s Board of Directors’ Decision no. (3/Chairman) of 2020 concerning Approval of Joint Stock Companies Governance Guide', 'Corporate Governance Guide provides the framework necessary for regulating the company affairs. The provisions stipulated therein are based on the provisions stipulated in the federal law No. 2 of 2015 concerning commercial companies. The present guide focuses on application of its articles, and its clauses are formulated in simple and clear way. All public joint stock companies are expected to comply with the regulation. The Securities and Commodities Authority will supervise the present guide application in its capacity the regulator of the listed companies. The main pillars of the corporate governance consist of accountability, fairness, disclosure, transparency and responsibility. The corporate governance is focused on guiding and supervising the companies. It consists of a set of controls and rules that ensure institutional discipline in the company relations and management. The framework complies with the international standards in terms of defining the responsibilities and duties of the members of board of directors and executive management. It observes also protection of rights of shareholders and stakeholders and their supervision and agency towards achieving the company sustainability.', 'Corporate Governance Guide provides the framework necessary for regulating the company affairs. The provisions stipulated therein are based on the provisions stipulated in the federal law No. 2 of 2015 concerning commercial companies. The present guide focuses on application of its articles, and its clauses are formulated in simple and clear way. All public joint stock companies are expected to comply with the regulation. The Securities and Commodities Authority will supervise the present guide application in its capacity the regulator of the listed companies. The main pillars of the corporate governance consist of accountability, fairness, disclosure, transparency and responsibility. The corporate governance is focused on guiding and supervising the companies. It consists of a set of controls and rules that ensure institutional discipline in the company relations and management. The framework complies with the international standards in terms of defining the responsibilities and duties of the members of board of directors and executive management. It observes also protection of rights of shareholders and stakeholders and their supervision and agency towards achieving the company sustainability.', 'Corporate Governance Guide provides the framework necessary for regulating the company affairs. The provisions stipulated therein are based on the provisions stipulated in the federal law No. 2 of 2015 concerning commercial companies. The present guide focuses on application of its articles, and its clauses are formulated in simple and clear way. All public joint stock companies are expected to comply with the regulation. The Securities and Commodities Authority will supervise the present guide application in its capacity the regulator of the listed companies. The main pillars of the corporate governance consist of accountability, fairness, disclosure, transparency and responsibility. The corporate governance is focused on guiding and supervising the companies. It consists of a set of controls and rules that ensure institutional discipline in the company relations and management. The framework complies with the international standards in terms of defining the responsibilities and duties of the members of board of directors and executive management. It observes also protection of rights of shareholders and stakeholders and their supervision and agency towards achieving the company sustainability.', 'UAE', 'governance', 'in_force', '2020-01-01'::date, 'United Arab Emirates', 'https://www.carrotsandsticks.org/policies/183_13', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'uae', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ff6aa155-6464-5ebf-bf10-3ad09883a581', 'UAE Governance Guide for Public Joint-Stock Companies Attached', 'The Governance Guide for Public Joint-Stock Companies 
Attached to the SCA Board Chairman’s Decision No. 
(3/Chairman) of 2020', 'This Governance Guide regulates corporate affairs. Its provisions are based on the provisions of the Federal Decree Law No. (32) of 2021 concerning Commercial Companies and any amendments thereto.  The Guide''s clauses are simply and clearly stated. All the public joint stock companies are expected to comply with the rules.', 'This Governance Guide regulates corporate affairs. Its provisions are based on the provisions of the Federal Decree Law No. (32) of 2021 concerning Commercial Companies and any amendments thereto.  The Guide''s clauses are simply and clearly stated. All the public joint stock companies are expected to comply with the rules.', 'This Governance Guide regulates corporate affairs. Its provisions are based on the provisions of the Federal Decree Law No. (32) of 2021 concerning Commercial Companies and any amendments thereto.  The Guide''s clauses are simply and clearly stated. All the public joint stock companies are expected to comply with the rules.', 'UAE', 'governance', 'in_force', '2020-01-01'::date, 'United Arab Emirates', 'https://www.carrotsandsticks.org/policies/183_21', ARRAY['regulations', 'mandatory', 'uae', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8c8c8590-dd10-5c3b-b5be-5d0465222289', 'UAE Abu Dhabi Securities Exchange ESG Disclosure Guidance', 'Abu Dhabi Securities Exchange ESG Disclosure Guidance for Listed Companies, 2019', 'This voluntary guidance provides ADX listed companies with 31 ESG indicators that are considered essential to report in alignment with the recommendations of the Sustainable Stock Exchanges (SSE) Initiative and the World Federation of Exchanges (WFE).', 'This voluntary guidance provides ADX listed companies with 31 ESG indicators that are considered essential to report in alignment with the recommendations of the Sustainable Stock Exchanges (SSE) Initiative and the World Federation of Exchanges (WFE).', 'This voluntary guidance provides ADX listed companies with 31 ESG indicators that are considered essential to report in alignment with the recommendations of the Sustainable Stock Exchanges (SSE) Initiative and the World Federation of Exchanges (WFE).', 'UAE', 'climate', 'in_force', '2019-01-01'::date, 'United Arab Emirates', 'https://www.carrotsandsticks.org/policies/183_11', ARRAY['guidance_frameworks', 'sdg13', 'mandatory', 'uae', 'sdg16', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('df5f538d-e3b1-5a81-afb8-53c39278331b', 'UAE Securities & Commodities Authority Master Plan for Sustainable', 'The Securities & Commodities Authority Master Plan for Sustainable Capital Markets', 'The plan aims to 1. Provide channels for funding of sustainable projects including those that support the environment, society, and the economy; and reallocate available capital to more sustainable projects. 2. Encourage corporates and their management to shift towards more effective sustainable practices. 3. Provide investment opportunities and information to investors to invest in such projects and allow them to make better decisions in this regard. 4. Create awareness with all market stakeholders on the importance of sustainability and their respective role in supporting it through their actions. It is comprised of 7 key pillars 1) Taxonomy, classification, and standard-setting. 2) Legal and regulatory framework. 3) Market platform and investment instruments. 4) Corporate Governance and stewardship. 5) Transparency and disclosure. 6) Awareness and education. 7) Awards and incentives.', 'The plan aims to 1. Provide channels for funding of sustainable projects including those that support the environment, society, and the economy; and reallocate available capital to more sustainable projects. 2. Encourage corporates and their management to shift towards more effective sustainable practices. 3. Provide investment opportunities and information to investors to invest in such projects and allow them to make better decisions in this regard. 4. Create awareness with all market stakeholders on the importance of sustainability and their respective role in supporting it through their actions. It is comprised of 7 key pillars 1) Taxonomy, classification, and standard-setting. 2) Legal and regulatory framework. 3) Market platform and investment instruments. 4) Corporate Governance and stewardship. 5) Transparency and disclosure. 6) Awareness and education. 7) Awards and incentives.', 'The plan aims to 1. Provide channels for funding of sustainable projects including those that support the environment, society, and the economy; and reallocate available capital to more sustainable projects. 2. Encourage corporates and their management to shift towards more effective sustainable practices. 3. Provide investment opportunities and information to investors to invest in such projects and allow them to make better decisions in this regard. 4. Create awareness with all market stakeholders on the importance of sustainability and their respective role in supporting it through their actions. It is comprised of 7 key pillars 1) Taxonomy, classification, and standard-setting. 2) Legal and regulatory framework. 3) Market platform and investment instruments. 4) Corporate Governance and stewardship. 5) Transparency and disclosure. 6) Awareness and education. 7) Awards and incentives.', 'UAE', 'climate', 'in_force', '2019-01-01'::date, 'United Arab Emirates', 'https://www.carrotsandsticks.org/policies/183_12', ARRAY['sdg4', 'other sustainability policy', 'mandatory', 'uae', 'sdg16', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5e607331-681b-5742-80a6-671190eacd19', 'UAE Dubai Financial Market ESG Reporting Guide', 'Dubai Financial Market ESG Reporting Guide', 'The Dubai Financial Market (DFM) ESG Reporting Guide provides voluntary guidelines to enhance the quality and consistency of Environmental, Social, and Governance (ESG) disclosures among listed companies in Dubai. The guide aligns with international frameworks, such as the Global Reporting Initiative (GRI), Sustainability Accounting Standards Board (SASB), and Task Force on Climate-related Financial Disclosures (TCFD), to ensure comparability and transparency in ESG reporting. Its objectives include increasing investor confidence, supporting sustainable investment practices, and aligning with the UAE’s commitment to the United Nations Sustainable Development Goals (SDGs).', 'The Dubai Financial Market (DFM) ESG Reporting Guide provides voluntary guidelines to enhance the quality and consistency of Environmental, Social, and Governance (ESG) disclosures among listed companies in Dubai. The guide aligns with international frameworks, such as the Global Reporting Initiative (GRI), Sustainability Accounting Standards Board (SASB), and Task Force on Climate-related Financial Disclosures (TCFD), to ensure comparability and transparency in ESG reporting. Its objectives include increasing investor confidence, supporting sustainable investment practices, and aligning with the UAE’s commitment to the United Nations Sustainable Development Goals (SDGs).', 'The Dubai Financial Market (DFM) ESG Reporting Guide provides voluntary guidelines to enhance the quality and consistency of Environmental, Social, and Governance (ESG) disclosures among listed companies in Dubai. The guide aligns with international frameworks, such as the Global Reporting Initiative (GRI), Sustainability Accounting Standards Board (SASB), and Task Force on Climate-related Financial Disclosures (TCFD), to ensure comparability and transparency in ESG reporting. Its objectives include increasing investor confidence, supporting sustainable investment practices, and aligning with the UAE’s commitment to the United Nations Sustainable Development Goals (SDGs).', 'UAE', 'climate', 'in_force', '2019-01-01'::date, 'United Arab Emirates', 'https://www.carrotsandsticks.org/policies/183_8', ARRAY['sdg13', 'sdg7', 'mandatory', 'uae', 'sdg16', 'mandatory_regulations', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('53db0ccb-d185-5634-a447-2436214642c4', 'UAE Chairman of Authority''s Board of Directors'' Decision No', 'The Chairman of Authority''s Board of Directors'' Decision No. (7 R.M) of 2016 Concerning the Standards of Institutional Discipline and Governance of Public Shareholding Companies', 'The Chairman of the Securities and Commodities Authority of the United Arab Emirates (SCA) issued on 28 April 2016 the Resolution No. (7/R.M) of 2016 Concerning Corporate Discipline and Governance Standards of Public Joint Stock Companies (New Governance Rules) in order to: List a set of new corporate governance rules in accordance with, and to adhere to, the Federal Law No.(2) of 2015 on Commercial Companies (CCL); and Repeal the UAE Ministerial Resolution No. (518) of 2009 Concerning Governance Rules and Corporate Discipline Standards (Repealed Governance Rules).', 'The Chairman of the Securities and Commodities Authority of the United Arab Emirates (SCA) issued on 28 April 2016 the Resolution No. (7/R.M) of 2016 Concerning Corporate Discipline and Governance Standards of Public Joint Stock Companies (New Governance Rules) in order to: List a set of new corporate governance rules in accordance with, and to adhere to, the Federal Law No.(2) of 2015 on Commercial Companies (CCL); and Repeal the UAE Ministerial Resolution No. (518) of 2009 Concerning Governance Rules and Corporate Discipline Standards (Repealed Governance Rules).', 'The Chairman of the Securities and Commodities Authority of the United Arab Emirates (SCA) issued on 28 April 2016 the Resolution No. (7/R.M) of 2016 Concerning Corporate Discipline and Governance Standards of Public Joint Stock Companies (New Governance Rules) in order to: List a set of new corporate governance rules in accordance with, and to adhere to, the Federal Law No.(2) of 2015 on Commercial Companies (CCL); and Repeal the UAE Ministerial Resolution No. (518) of 2009 Concerning Governance Rules and Corporate Discipline Standards (Repealed Governance Rules).', 'UAE', 'governance', 'in_force', '2016-01-01'::date, 'United Arab Emirates', 'https://www.carrotsandsticks.org/policies/183_10', ARRAY['voluntary_frameworks', 'other sustainability policy', 'uae', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8075ca26-9da4-5c7c-b4bb-060e7f287478', 'UAE Resolution No (7RM) of 2016 Concerning the Standards', 'Resolution No (7RM) of 2016 Concerning the Standards of Institutional Discipline and Governance of Public Shareholding Companies', 'In 2016, the Chairman of the United Arab Emirates'' Securities and Commodities Authority''s Board of Directors issued Resolution No. (7 R.M) which established new standards for the institutional discipline and governance of public shareholding companies in the UAE. The resolution outlines requirements for the composition and responsibilities of the board of directors, as well as procedures for the election of board members and the appointment of executive management. It also establishes requirements for financial reporting and disclosure, including the publication of annual reports, financial statements, and other information relevant to shareholders. Additionally, the resolution mandates that public shareholding companies establish policies and procedures to prevent conflicts of interest and insider trading, and requires the establishment of an internal audit function and the appointment of an external auditor. The resolution is intended to promote transparency and accountability in the governance of public shareholding companies in the UAE and ensure compliance with international standards of good corporate governance.', 'In 2016, the Chairman of the United Arab Emirates'' Securities and Commodities Authority''s Board of Directors issued Resolution No. (7 R.M) which established new standards for the institutional discipline and governance of public shareholding companies in the UAE. The resolution outlines requirements for the composition and responsibilities of the board of directors, as well as procedures for the election of board members and the appointment of executive management. It also establishes requirements for financial reporting and disclosure, including the publication of annual reports, financial statements, and other information relevant to shareholders. Additionally, the resolution mandates that public shareholding companies establish policies and procedures to prevent conflicts of interest and insider trading, and requires the establishment of an internal audit function and the appointment of an external auditor. The resolution is intended to promote transparency and accountability in the governance of public shareholding companies in the UAE and ensure compliance with international standards of good corporate governance.', 'In 2016, the Chairman of the United Arab Emirates'' Securities and Commodities Authority''s Board of Directors issued Resolution No. (7 R.M) which established new standards for the institutional discipline and governance of public shareholding companies in the UAE. The resolution outlines requirements for the composition and responsibilities of the board of directors, as well as procedures for the election of board members and the appointment of executive management. It also establishes requirements for financial reporting and disclosure, including the publication of annual reports, financial statements, and other information relevant to shareholders. Additionally, the resolution mandates that public shareholding companies establish policies and procedures to prevent conflicts of interest and insider trading, and requires the establishment of an internal audit function and the appointment of an external auditor. The resolution is intended to promote transparency and accountability in the governance of public shareholding companies in the UAE and ensure compliance with international standards of good corporate governance.', 'UAE', 'climate', 'in_force', '2016-01-01'::date, 'United Arab Emirates', 'https://www.carrotsandsticks.org/policies/183_17', ARRAY['voluntary_frameworks', 'uae', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f0bce6a0-8998-5ea7-91a2-e865ed264692', 'UAE Federal Law No. (2) concerning Commercial Companies (CCL)', 'Federal Law No. (2) concerning Commercial Companies (CCL)', 'Public joint stock companies can, after two years of their incorporation and of making a profit, allocate funds (not exceeding 2% of the average net profits of the company during the two successive years preceding the year it makes the contribution) to corporate social responsibility. The beneficiary of such contributions should be stated in the company''s auditor''s report and balance sheet.', 'Public joint stock companies can, after two years of their incorporation and of making a profit, allocate funds (not exceeding 2% of the average net profits of the company during the two successive years preceding the year it makes the contribution) to corporate social responsibility. The beneficiary of such contributions should be stated in the company''s auditor''s report and balance sheet.', 'Public joint stock companies can, after two years of their incorporation and of making a profit, allocate funds (not exceeding 2% of the average net profits of the company during the two successive years preceding the year it makes the contribution) to corporate social responsibility. The beneficiary of such contributions should be stated in the company''s auditor''s report and balance sheet.', 'UAE', 'climate', 'in_force', '2015-01-01'::date, 'United Arab Emirates', 'https://www.carrotsandsticks.org/policies/183_5', ARRAY['mandatory', 'uae', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a000a937-3bb6-52e7-a54b-3238af0314c4', 'UAE Green Building Regulations and Specifications', 'Green Building Regulations and Specifications', 'The purpose of the regulations is to improve the performance of buildings in Dubai by reducing the consumption of energy, water and materials, improving public health, safety and general welfare and by enhancing the planning, design, construction and operation of buildings to create an excellent city that provides the essence of success and comfort of living.', 'The purpose of the regulations is to improve the performance of buildings in Dubai by reducing the consumption of energy, water and materials, improving public health, safety and general welfare and by enhancing the planning, design, construction and operation of buildings to create an excellent city that provides the essence of success and comfort of living.', 'The purpose of the regulations is to improve the performance of buildings in Dubai by reducing the consumption of energy, water and materials, improving public health, safety and general welfare and by enhancing the planning, design, construction and operation of buildings to create an excellent city that provides the essence of success and comfort of living.', 'UAE', 'climate', 'in_force', '2010-01-01'::date, 'United Arab Emirates', 'https://www.carrotsandsticks.org/policies/183_4', ARRAY['other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'uae', 'sdg6', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('39cefa18-540d-50b3-b6c4-1ef79708e5c0', 'UAE Ministerial Resolution No. (518) of 2009 Concerning Governance', 'Ministerial Resolution No. (518) of 2009 Concerning Governance Rules and Corporate Discipline Standards', 'It requires companies to issue a Governance Report and submitted to the Authority on annual basis, it states the importance of verification of financial/and non-financial reports and states the need for a company''s code of conduct to incorporate environmental and social policy towards the local society.', 'It requires companies to issue a Governance Report and submitted to the Authority on annual basis, it states the importance of verification of financial/and non-financial reports and states the need for a company''s code of conduct to incorporate environmental and social policy towards the local society.', 'It requires companies to issue a Governance Report and submitted to the Authority on annual basis, it states the importance of verification of financial/and non-financial reports and states the need for a company''s code of conduct to incorporate environmental and social policy towards the local society.', 'UAE', 'climate', 'in_force', '2009-01-01'::date, 'United Arab Emirates', 'https://www.carrotsandsticks.org/policies/183_9', ARRAY['voluntary_frameworks', 'other sustainability policy', 'uae', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('43dd6d45-e0ca-550c-8b07-1bc0a3ec9bc5', 'UAE Federal Law No. (23) Of the year 1999', 'Federal Law No. (23) Of the year 1999 concerning Exploitation, Protection and Development of the Living Aquatic Resources In the State Of The United Arab Emirates', 'This legislation covers the protection of the marine environment and resource.', 'This legislation covers the protection of the marine environment and resource.', 'This legislation covers the protection of the marine environment and resource.', 'UAE', 'nature', 'in_force', '1999-01-01'::date, 'United Arab Emirates', 'https://www.carrotsandsticks.org/policies/183_6', ARRAY['sdg14', 'other sustainability policy', 'regulations', 'mandatory', 'uae']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f774f51d-8f2f-5c09-8b7b-18061b0f8e99', 'UAE Federal Law No. (24) for Protection and Development', 'Federal Law No. (24) for Protection and Development of the Environment', 'This law aims to ensure the protection and conservation of the quality and natural balance of the environment as well as to control all forms of pollution and avoid any immediate or long-term harmful effects resulting from economic, agricultural and industrial developments.', 'This law aims to ensure the protection and conservation of the quality and natural balance of the environment as well as to control all forms of pollution and avoid any immediate or long-term harmful effects resulting from economic, agricultural and industrial developments.', 'This law aims to ensure the protection and conservation of the quality and natural balance of the environment as well as to control all forms of pollution and avoid any immediate or long-term harmful effects resulting from economic, agricultural and industrial developments.', 'UAE', 'nature', 'in_force', '1999-01-01'::date, 'United Arab Emirates', 'https://www.carrotsandsticks.org/policies/183_7', ARRAY['mandatory', 'uae', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
