INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('23d81916-a49e-5c53-be67-91a919be11e7', 'Draft UK SRS S1', 'Draft UK SRS S1', 'The Draft UK SRS S1 outlines requirements for disclosing sustainability-related financial information, aiming to guide UK entities in reporting governance, strategy, risk management, metrics, and more. Intended users include professionals providing accounting services for financial and sustainability reports, with clear restrictions on commercial use.', 'The Draft UK SRS S1 outlines requirements for disclosing sustainability-related financial information, aiming to guide UK entities in reporting governance, strategy, risk management, metrics, and more. Intended users include professionals providing accounting services for financial and sustainability reports, with clear restrictions on commercial use.', 'The Draft UK SRS S1 outlines requirements for disclosing sustainability-related financial information, aiming to guide UK entities in reporting governance, strategy, risk management, metrics, and more. Intended users include professionals providing accounting services for financial and sustainability reports, with clear restrictions on commercial use.', 'UK', 'climate', 'in_force', '2025-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/185_114', ARRAY['sdg16', 'mandatory', 'mandatory_regulations', 'uk']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('799c568c-dceb-597d-a52d-70f93cbca264', 'Draft UK SRS S2 Climate-related disclosures', 'Draft UK SRS S2 Climate-related disclosures', 'The Draft UK SRS S2 Climate-related disclosures aim to require entities to disclose climate-related risks and opportunities affecting cash flows and access to finance. It outlines governance, strategy, risk management, and metrics. Targeted at users of general financial reports for informed decision-making on resource allocation to entities.', 'The Draft UK SRS S2 Climate-related disclosures aim to require entities to disclose climate-related risks and opportunities affecting cash flows and access to finance. It outlines governance, strategy, risk management, and metrics. Targeted at users of general financial reports for informed decision-making on resource allocation to entities.', 'The Draft UK SRS S2 Climate-related disclosures aim to require entities to disclose climate-related risks and opportunities affecting cash flows and access to finance. It outlines governance, strategy, risk management, and metrics. Targeted at users of general financial reports for informed decision-making on resource allocation to entities.', 'UK', 'climate', 'in_force', '2025-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/185_115', ARRAY['sdg13', 'uk', 'mandatory', 'sdg16', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f6b0f3f0-c3d3-5e31-910a-9da338df5b62', 'UK PAS 51215-1:2025 Energy and decarbonization assessment – Part', 'PAS 51215-1:2025 Energy and decarbonization assessment – Part 1: Process – Specification', 'PAS 51215-1:2025 outlines the process for energy and decarbonization assessment, focusing on defining boundaries, data collection, analysis, and reporting. The policy targets assessors involved in evaluating energy practices to achieve net zero emissions by 2050 or earlier in the UK.', 'PAS 51215-1:2025 outlines the process for energy and decarbonization assessment, focusing on defining boundaries, data collection, analysis, and reporting. The policy targets assessors involved in evaluating energy practices to achieve net zero emissions by 2050 or earlier in the UK.', 'PAS 51215-1:2025 outlines the process for energy and decarbonization assessment, focusing on defining boundaries, data collection, analysis, and reporting. The policy targets assessors involved in evaluating energy practices to achieve net zero emissions by 2050 or earlier in the UK.', 'UK', 'climate', 'in_force', '2025-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/185_118', ARRAY['sdg13', 'uk', 'sdg7', 'regulations', 'mandatory']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('80b7ae96-129d-518d-9dd2-cc6879b2411d', 'UK PAS 51215-2:2025 Energy and decarbonization assessment – Part', 'PAS 51215-2:2025 Energy and decarbonization assessment – Part 2: Competencies of lead assessors and assessment teams –Specification', 'PAS 51215-2:2025 outlines competencies for lead assessors and assessment teams in energy and decarbonization assessments. Published in the UK, it specifies professional conduct, required competencies, and the process for gaining and maintaining lead assessor status. Target audience includes energy professionals and environmental assessors.', 'PAS 51215-2:2025 outlines competencies for lead assessors and assessment teams in energy and decarbonization assessments. Published in the UK, it specifies professional conduct, required competencies, and the process for gaining and maintaining lead assessor status. Target audience includes energy professionals and environmental assessors.', 'PAS 51215-2:2025 outlines competencies for lead assessors and assessment teams in energy and decarbonization assessments. Published in the UK, it specifies professional conduct, required competencies, and the process for gaining and maintaining lead assessor status. Target audience includes energy professionals and environmental assessors.', 'UK', 'climate', 'in_force', '2025-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/185_119', ARRAY['sdg13', 'uk', 'sdg7', 'mandatory', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('fe0b1fef-6b19-5977-bf92-67b6c40ccd77', 'UK Finance () Bill', 'Finance (No. 2) Bill', 'The Finance (No. 2) Bill outlines tax changes for income, capital gains, and corporate taxes in the UK for 2025. It includes provisions on employee reliefs, capital allowances, international tax matters, inheritance tax, and other existing taxes. This policy targets taxpayers, businesses, and tax professionals.', 'The Finance (No. 2) Bill outlines tax changes for income, capital gains, and corporate taxes in the UK for 2025. It includes provisions on employee reliefs, capital allowances, international tax matters, inheritance tax, and other existing taxes. This policy targets taxpayers, businesses, and tax professionals.', 'The Finance (No. 2) Bill outlines tax changes for income, capital gains, and corporate taxes in the UK for 2025. It includes provisions on employee reliefs, capital allowances, international tax matters, inheritance tax, and other existing taxes. This policy targets taxpayers, businesses, and tax professionals.', 'UK', 'governance', 'in_force', '2025-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/185_120', ARRAY['mandatory', 'mandatory_regulations', 'uk']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('61058466-4322-5a35-b41f-684aafdd903d', 'UK Primary Market / TN / 802.2 TCFD aligned', 'Primary Market / TN / 802.2 TCFD aligned climate-related disclosure requirements for listed companies', 'The UK''s 2025 Primary Market Technical Note outlines TCFD-aligned climate disclosure requirements for listed companies, emphasizing transparency and consistency in financial reporting. Issuers must disclose climate-related financial information in annual reports to aid investor decision-making, ensuring compliance with the UK Listing Rules.', 'The UK''s 2025 Primary Market Technical Note outlines TCFD-aligned climate disclosure requirements for listed companies, emphasizing transparency and consistency in financial reporting. Issuers must disclose climate-related financial information in annual reports to aid investor decision-making, ensuring compliance with the UK Listing Rules.', 'The UK''s 2025 Primary Market Technical Note outlines TCFD-aligned climate disclosure requirements for listed companies, emphasizing transparency and consistency in financial reporting. Issuers must disclose climate-related financial information in annual reports to aid investor decision-making, ensuring compliance with the UK Listing Rules.', 'UK', 'climate', 'in_force', '2025-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/185_126', ARRAY['sdg13', 'uk', 'mandatory', 'sdg16', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('568659c1-3716-558d-8fbe-acb1a925d430', 'UK Finance Act', 'Finance Act 2025', 'The Finance Act 2025 in the United Kingdom outlines income tax, capital gains tax, and corporate tax regulations for the tax year 2025-26. It sets rates for different income levels and provides guidelines for taxation on cars based on their CO2 emissions and cylinder capacity. Targeted at taxpayers and businesses in the UK.', 'The Finance Act 2025 in the United Kingdom outlines income tax, capital gains tax, and corporate tax regulations for the tax year 2025-26. It sets rates for different income levels and provides guidelines for taxation on cars based on their CO2 emissions and cylinder capacity. Targeted at taxpayers and businesses in the UK.', 'The Finance Act 2025 in the United Kingdom outlines income tax, capital gains tax, and corporate tax regulations for the tax year 2025-26. It sets rates for different income levels and provides guidelines for taxation on cars based on their CO2 emissions and cylinder capacity. Targeted at taxpayers and businesses in the UK.', 'UK', 'climate', 'in_force', '2025-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/185_127', ARRAY['mandatory', 'uk', 'sdg13', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f1db4420-ed91-5261-a1e2-d80fa1991e35', 'UK Task Force on Climate-related Financial Disclosure (TCFD) –', 'Task Force on Climate-related Financial Disclosure (TCFD) – Aligned Disclosure Application Guidance (UK, 2024)', 'This guidance, issued by HM Treasury, provides a structured approach for UK public sector entities to adopt TCFD-aligned climate-related financial disclosures in their annual reports. The guidance aims to improve climate risk transparency, enhance decision-making, and align public sector reporting with private sector standards.

Key provisions include:

Scope & Applicability:
Applies to central government departments, arm’s-length bodies (ALBs) with 500+ employees or £500M+ annual income, and other public sector bodies directed by their sponsoring departments.
Voluntary adoption encouraged for other entities.
TCFD Four-Pillar Framework:
Governance: How climate-related risks and opportunities are overseen at board and management levels.
Strategy: Impact of climate risks and opportunities on financial planning, operations, and resilience.
Risk Management: How climate risks are identified, assessed, and integrated into broader risk frameworks.
Metrics & Targets: Climate-related KPIs, Scope 1 & 2 GHG emissions (mandatory), and other relevant disclosures.
Compliance & Review:
Mandatory disclosures include governance, risk management, and Scope 1 & 2 emissions reporting.
Materiality assessment applies to strategy and additional metrics.
Public sector bodies must provide a TCFD Compliance Statement outlining adherence to disclosure requirements.
Alignment with International Standards:
The guidance is compatible with UK Sustainability Reporting Standards (UK SRS) (expected in 2025), Financial Conduct Authority (FCA) Climate Disclosure Rules, and Paris Agreement commitments.
This framework enhances climate-related financial transparency in UK public sector reporting, supporting better policy alignment and risk mitigation.', 'This guidance, issued by HM Treasury, provides a structured approach for UK public sector entities to adopt TCFD-aligned climate-related financial disclosures in their annual reports. The guidance aims to improve climate risk transparency, enhance decision-making, and align public sector reporting with private sector standards.

